s]"},{"word":"home."},{"word":"How"},{"word":"many"},{"word":"[things]"},{"word":"are"},{"word":"still"},{"word":"there?"}]}]},"hash":"0483a6e9cd2d80833349a63df030b80f929bec8afa57a6aca59592e02b69c029"},{"kind":"question","key":"juice-left","position":4,"content":{"id":"juice-left","scenarioKind":"pour","slots":{"jugs":{"min":2,"max":5},"size":{"min":3,"max":4},"drunk":{"min":2,"max":4}},"unit":"[unit.volume]","solver":{"op":"-","left":{"op":"×","left":{"slot":"jugs"},"right":{"slot":"size"}},"right":{"slot":"drunk"}},"difficulty":3,"phrasings":[{"id":"fills","tokens":[{"word":"Each"},{"word":"[container]"},{"word":"holds"},{"word":"[size]"},{"word":"[units.volume]"},{"word":"of"},{"word":"juice."},{"word":"Mo"},{"word":"fills"},{"word":"[jugs]"},{"word":"[containers]"},{"word":"for"},{"word":"the"},{"word":"[place]."},{"word":"The"},{"word":"family"},{"word":"drinks"},{"word":"[drunk]"},{"word":"[units.volume]."},{"word":"How"},{"word":"much"},{"word":"juice"},{"word":"is"},{"word":"left?"}]},{"id":"spills","tokens":[{"word":"Mo"},{"word":"pours"},{"word":"[size]"},{"word":"[units.volume]"},{"word":"of"},{"word":"juice"},{"word":"into"},{"word":"each"},{"word":"of"},{"word":"[jugs]"},{"word":"[containers]."},{"word":"Then"},{"word":"[drunk]"},{"word":"[units.volume]"},{"word":"spill"},{"word":"on"},{"word":"the"},{"word":"grass."},{"word":"How"},{"word":"much"},{"word":"juice"},{"word":"is"},{"word":"in"},{"word":"the"},{"word":"[containers]"},{"word":"now?"}]}]},"hash":"347de1e8286a380fa06d101be6cbc3c627942ee6e0e3b826dc8709d78f17291b"},{"kind":"question","key":"toonie-savings","position":5,"content":{"id":"toonie-savings","scenarioKind":"coins","regions":["CA"],"slots":{"count":{"min":2,"max":9}},"unit":"[unit.money]","solver":{"op":"×","left":{"slot":"count"},"right":{"number":2}},"difficulty":2,"phrasings":[{"id":"saves","tokens":[{"word":"Pia"},{"word":"saves"},{"word":"[count]"},{"word":"[coins.toonie]"},{"word":"in"},{"word":"a"},{"word":"[container]."},{"word":"A"},{"word":"[coin.toonie]"},{"word":"is"},{"word":"worth"},{"word":"two"},{"word":"dollars."},{"word":"How"},{"word":"many"},{"word":"dollars"},{"word":"does"},{"word":"Pia"},{"word":"have?"}]},{"id":"finds","tokens":[{"word":"Pia"},{"word":"finds"},{"word":"[count]"},{"word":"[coins.toonie]"},{"word":"at"},{"word":"the"},{"word":"[place]."},{"word":"Each"},{"word":"[coin.toonie]"},{"word":"is"},{"word":"two"},{"word":"dollars."},{"word":"How"},{"word":"many"},{"word":"dollars"},{"word":"is"},{"word":"that?"}]}]},"hash":"08e785da6cf0077ea03ab095bec9dc5256911a91924d79d31ac5d6c0daefacf6"},{"kind":"question","key":"nickels-to-pennies","position":6,"content":{"id":"nickels-to-pennies","scenarioKind":"coins","regions":["US"],"slots":{"count":{"min":2,"max":9}},"unit":"[unit.cent]","solver":{"op":"×","left":{"slot":"count"},"right":{"number":5}},"difficulty":2,"phrasings":[{"id":"trades","tokens":[{"word":"A"},{"word":"[coin.nickel]"},{"word":"is"},{"word":"worth"},{"word":"five"},{"word":"[coins.penny]."},{"word":"Pia"},{"word":"trades"},{"word":"[count]"},{"word":"[coins.nickel]"},{"word":"for"},{"word":"[coins.penny]."},{"word":"How"},{"word":"many"},{"word":"cents"},{"word":"does"},{"word":"she"},{"word":"get?"}]},{"id":"jar","tokens":[{"word":"Pia"},{"word":"has"},{"word":"[count]"},{"word":"[coins.nickel]"},{"word":"in"},{"word":"a"},{"word":"[container]."},{"word":"Each"},{"word":"one"},{"word":"is"},{"word":"worth"},{"word":"five"},{"word":"[coins.penny]."},{"word":"How"},{"word":"many"},{"word":"cents"},{"word":"are"},{"word":"in"},{"word":"the"},{"word":"[container]?"}]}]},"hash":"9b6d6b9d063bb208c0329b7c93d8100a8239e55f72ff3d697808b55b8ab32fd5"},{"kind":"scenario","key":"bakery-boxes","position":0,"content":{"id":"bakery-boxes","interest":"default","kind":"groups","place":"bakery","container":{"one":"box","many":"boxes"},"thing":{"one":"muffin","many":"muffins"},"verb":"packs","unit":{"one":"muffin","many":"muffins"},"quantityLimits":{"groups":{"min":2,"max":9},"each":{"min":2,"max":12},"taken":{"min":2,"max":4}}},"hash":"bc02fc1e102682e13ef68bff08019b8b84f2da2737f6101d75bf53c7e77aafbf"},{"kind":"scenario","key":"station-crates","position":1,"content":{"id":"station-crates","interest":"space","kind":"groups","place":"space station","container":{"one":"crate","many":"crates"},"thing":{"one":"moon rock","many":"moon rocks"},"verb":"loads","unit":{"one":"moon rock","many":"moon rocks"},"quantityLimits":{"groups":{"min":2,"max":6},"each":{"min":2,"max":10},"taken":{"min":2,"max":4}}},"hash":"4fd0ecaa3d6c8d4993b096a324bcbd55c8e2751d8a293bb70b8b63134cc8d267"},{"kind":"scenario","key":"class-stickers","position":2,"content":{"id":"class-stickers","interest":"default","kind":"share","place":"classroom","container":{"one":"sheet","many":"sheets"},"thing":{"one":"sticker","many":"stickers"},"verb":"shares","unit":{"one":"sticker","many":"stickers"},"quantityLimits":{"count":{"min":4,"max":40}}},"hash":"61b129b28ded914facf39522b77e4a01dfe191fae31ae5659d6fda87695f0f11"},{"kind":"scenario","key":"rocket-snacks","position":3,"content":{"id":"rocket-snacks","interest":"space","kind":"share","place":"rocket","container":{"one":"pouch","many":"pouches"},"thing":{"one":"snack bar","many":"snack bars"},"verb":"packs","unit":{"one":"snack bar","many":"snack bars"},"quantityLimits":{"count":{"min":4,"max":30}}},"hash":"79fa5fd48028e5fe9c91ceceeeeb71987d91b7b97306caed7da800aed10aa67a"},{"kind":"scenario","key":"craft-ribbon","position":4,"content":{"id":"craft-ribbon","interest":"default","kind":"measure","place":"craft table","container":{"one":"spool","many":"spools"},"thing":{"one":"ribbon","many":"ribbons"},"verb":"cuts","unit":{"one":"ribbon","many":"ribbons"},"quantityLimits":{"length":{"min":25,"max":90},"cut":{"min":5,"max":19}}},"hash":"4cbf2dbc054bc89cad74956410f5e2a8d9c9acbc45db3e2a3106c3ffc232b647"},{"kind":"scenario","key":"picnic-juice","position":5,"content":{"id":"picnic-juice","interest":"default","kind":"pour","place":"picnic","container":{"one":"jug","many":"jugs"},"thing":{"one":"cup","many":"cups"},"verb":"pours","unit":{"one":"cup","many":"cups"},"quantityLimits":{"jugs":{"min":2,"max":5},"size":{"min":3,"max":4},"drunk":{"min":2,"max":4}}},"hash":"91a98a998bc643b88951e2f023f443ba7c1d5c18461c1d2cea2f5259a2bced2d"},{"kind":"scenario","key":"piggy-bank","position":6,"content":{"id":"piggy-bank","interest":"default","kind":"coins","place":"toy shop","container":{"one":"jar","many":"jars"},"thing":{"one":"coin","many":"coins"},"verb":"saves","unit":{"one":"coin","many":"coins"},"quantityLimits":{"count":{"min":2,"max":9}}},"hash":"815ba5959bd50a8946ee9c469d17625a7b4ebbb467282f950beab1d8b34defdc"},{"kind":"region_pack","key":"CA","position":0,"content":{"id":"CA","units":{"length":{"one":"centimetre","many":"centimetres"},"volume":{"one":"litre","many":"litres"},"money":{"one":"dollar","many":"dollars"},"cent":{"one":"cent","many":"cents"}},"coins":{"rounding":"nearest-5-cents","list":[{"id":"loonie","one":"loonie","many":"loonies","cents":100},{"id":"toonie","one":"toonie","many":"toonies","cents":200},{"id":"quarter","one":"quarter","many":"quarters","cents":25},{"id":"dime","one":"dime","many":"dimes","cents":10},{"id":"nickel","one":"nickel","many":"nickels","cents":5}]},"spelling":{"colour":"colour","metre":"metre","litre":"litre","favourite":"favourite"}},"hash":"3224dee78bdc2497012173f7c15a0f6e9102d2c2433487592320599ba2dbc0d9"},{"kind":"region_pack","key":"US","position":1,"content":{"id":"US","units":{"length":{"one":"inch","many":"inches"},"volume":{"one":"quart","many":"quarts"},"money":{"one":"dollar","many":"dollars"},"cent":{"one":"cent","many":"cents"}},"coins":{"rounding":"none","list":[{"id":"dollar","one":"dollar coin","many":"dollar coins","cents":100},{"id":"quarter","one":"quarter","many":"quarters","cents":25},{"id":"dime","one":"dime","many":"dimes","cents":10},{"id":"nickel","one":"nickel","many":"nickels","cents":5},{"id":"penny","one":"penny","many":"pennies","cents":1}]},"spelling":{"colour":"color","metre":"meter","litre":"liter","favourite":"favorite"}},"hash":"e363c62a40ebd95701c142d952f160a97bb5867acc13a54bc2e25034d432bbac"}]}$f$::jsonb;
  v_steps jsonb := '{}'::jsonb;
  v_ver text;
  v_sheet jsonb;
  v_res jsonb;
  v_snapshot uuid;
  v_state text;
  v_msg text;
begin
  if exists (select 1 from public.bank_levels where id = v_level) then
    raise exception 'UNI242_PROBE {"abort":"synthetic level already exists"}';
  end if;

  -- 0. Migration objects, RLS, grants.
  v_steps := v_steps || jsonb_build_object('0_triggers', case when (select count(*) from pg_trigger where not tgisinternal and tgname in (
    'bank_sheets_require_new_revision','bank_questions_require_new_revision','bank_scenarios_require_new_revision','bank_region_packs_require_new_revision',
    'bank_reviews_current_revision','bank_snapshots_insert_guard','bank_snapshot_items_insert_guard',
    'bank_reviews_refuse_statement','bank_snapshots_refuse_statement','bank_snapshot_items_refuse_statement')) = 10 then 'pass' else 'fail:missing triggers' end);
  v_steps := v_steps || jsonb_build_object('0_rls_no_policies', case when (select bool_and(c.relrowsecurity) from pg_class c where c.oid in ('public.bank_reviews'::regclass, 'public.bank_snapshots'::regclass, 'public.bank_snapshot_items'::regclass))
    and not exists (select 1 from pg_policies where schemaname = 'public' and tablename in ('bank_reviews','bank_snapshots','bank_snapshot_items')) then 'pass' else 'fail:rls or policy' end);
  v_steps := v_steps || jsonb_build_object('0_grants', case when not has_table_privilege('anon', 'public.bank_snapshot_items', 'select') and not has_table_privilege('authenticated', 'public.bank_reviews', 'insert')
    and not has_function_privilege('anon', 'public.bank_freeze_level(jsonb)', 'execute') and has_function_privilege('service_role', 'public.bank_freeze_level(jsonb)', 'execute')
    and has_function_privilege('service_role', 'public.bank_require_new_revision()', 'execute') and not has_function_privilege('anon', 'public.bank_review_current_revision()', 'execute') then 'pass' else 'fail:grants' end);

  -- 1. Import the synthetic level through bank_write_level.
  v_ver := public.bank_write_level(v_write)->>'version';
  v_steps := v_steps || jsonb_build_object('1_import', case when v_ver is not null then 'pass' else 'fail:no version' end);

  -- 2. An edit that keeps its revision is refused (PT409); a lower revision too.
  v_sheet := v_write->'sheets'->0;
  begin
    perform public.bank_write_level(jsonb_set(jsonb_set(v_write - 'sheets', '{expected}', to_jsonb(v_ver)), '{sheets}',
      jsonb_build_array(jsonb_set(v_sheet, '{content,front,instruction}', '"Changed after approval."'))));
    v_steps := v_steps || '{"2_same_revision_edit":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('2_same_revision_edit', case when v_state = 'PT409' and v_msg like '%an edit needs a new revision%' then 'pass' else 'fail:' || v_state || ' ' || v_msg end);
  end;
  -- A valid edit to revision 2, then a write back to revision 1; the block is undone, so the level stays as imported.
  v_msg := 'fail:not run';
  begin
    v_res := public.bank_write_level(jsonb_set(jsonb_set(v_write - 'sheets', '{expected}', to_jsonb(v_ver)), '{sheets}',
      jsonb_build_array(jsonb_set(jsonb_set(v_sheet, '{revision}', '2'), '{content,front,instruction}', '"Changed as revision 2."'))));
    begin
      perform public.bank_write_level(jsonb_set(jsonb_set(v_write - 'sheets', '{expected}', v_res->'version'), '{sheets}', jsonb_build_array(v_sheet)));
      v_msg := 'fail:accepted';
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
      v_msg := case when v_state = 'PT409' and v_msg like '%would go back from revision 2 to 1%' then 'pass' else 'fail:' || v_state || ' ' || v_msg end;
    end;
    raise exception 'probe-undo';
  exception when others then
    if sqlerrm <> 'probe-undo' then v_msg := 'fail:' || sqlerrm; end if;
  end;
  v_steps := v_steps || jsonb_build_object('2_lower_revision', v_msg);

  -- 3. A review of a revision the item is not at is refused under the level lock.
  begin
    insert into public.bank_reviews (level_id, item_kind, item_key, revision, reviewer, decision) values (v_level, 'sheet', v_sheet->>'sheet_id', 2, 'Probe reviewer', 'approved');
    v_steps := v_steps || '{"3_future_review":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('3_future_review', case when v_state = 'PT409' then 'pass' else 'fail:' || v_state end);
  end;

  -- 4. Approve every live item at its current revision.
  insert into public.bank_reviews (level_id, item_kind, item_key, revision, reviewer, decision)
  select v_level, l.kind, l.key, l.revision, 'Probe reviewer', 'approved' from public.bank_live_items(v_level) l;
  v_steps := v_steps || jsonb_build_object('4_approve_all', case when (select count(*) from public.bank_reviews where level_id = v_level) = (select count(*) from public.bank_live_items(v_level)) then 'pass' else 'fail:count' end);

  v_freeze := jsonb_set(v_freeze, '{expected}', to_jsonb(v_ver));

  -- 5. Items that differ from the working copy are refused: a topic title, a sheet place, the level header.
  begin
    perform public.bank_freeze_level(jsonb_set(v_freeze, '{items}', (select jsonb_agg(case when i->>'kind' = 'topic' then jsonb_set(i, '{content,title}', '"Changed title"') else i end) from jsonb_array_elements(v_freeze->'items') i)));
    v_steps := v_steps || '{"5_tampered_topic":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('5_tampered_topic', case when v_state = 'PT409' and v_msg like '%not the approved working copy%' then 'pass' else 'fail:' || v_state || ' ' || v_msg end);
  end;
  begin
    perform public.bank_freeze_level(jsonb_set(v_freeze, '{items}', (select jsonb_agg(case when i->>'kind' = 'level' then jsonb_set(i, '{content,level,name}', '"4"') else i end) from jsonb_array_elements(v_freeze->'items') i)));
    v_steps := v_steps || '{"5_tampered_header":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('5_tampered_header', case when v_state = 'PT409' and v_msg like '%not the approved working copy%' then 'pass' else 'fail:' || v_state || ' ' || v_msg end);
  end;

  -- Clearing the default region needs an explicit refusal while the story rows remain live.
  begin
    update public.bank_levels set default_region = null where id = v_level;
    begin
      perform public.bank_freeze_level(jsonb_set(v_freeze, '{expected}', (
        select to_jsonb(updated_at::text) from public.bank_levels where id = v_level)));
      v_steps := v_steps || '{"5_missing_story_region":"fail:accepted"}';
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
      v_steps := v_steps || jsonb_build_object('5_missing_story_region', case
        when v_state = 'PT409' and v_msg like '%set a default region or retire its questions, scenarios and region packs%'
        then 'pass' else 'fail:' || v_state || ' ' || v_msg end);
    end;
    raise exception 'restore probe region';
  exception when raise_exception then
    if sqlerrm <> 'restore probe region' then raise; end if;
  end;

  -- 6. The exact working copy freezes. This proves the SQL items match the TypeScript items (frozenItems).
  begin
    v_res := public.bank_freeze_level(v_freeze);
    v_snapshot := (v_res->>'snapshotId')::uuid;
    v_steps := v_steps || jsonb_build_object('6_freeze', case when (v_res->>'version')::integer = 1 then 'pass' else 'fail:' || v_res::text end);
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('6_freeze', 'fail:' || v_state || ' ' || left(v_msg, 1500));
  end;
  v_steps := v_steps || jsonb_build_object('6_flag_restored', case when coalesce(current_setting('unica.in_bank_freeze_level', true), '') = '' then 'pass' else 'fail:flag left set' end);

  -- 7. The same version again is refused (PT409, never 40001).
  begin
    perform public.bank_freeze_level(v_freeze);
    v_steps := v_steps || '{"7_version_taken":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('7_version_taken', case
      when v_state = 'PT409' and v_msg like '%version 1 is taken or skipped%next version is 2%' then 'pass'
      else 'fail:' || v_state || ' ' || v_msg end);
  end;

  -- 8. No item can be added after the freeze, and no snapshot outside bank_freeze_level (55000).
  begin
    insert into public.bank_snapshot_items (snapshot_id, kind, key, position, content, hash)
    values (v_snapshot, 'region_pack', 'XX', 9, '{"id":"XX"}', repeat('0', 64));
    v_steps := v_steps || '{"8_append_item":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('8_append_item', case when v_state = '55000' then 'pass' else 'fail:' || v_state end);
  end;
  begin
    insert into public.bank_snapshots (level_id, version, name, content_hash, manifest_hash, min_engine_version, item_count, frozen_by)
    values (v_level, 9, v_level || '-v9', repeat('0', 64), repeat('0', 64), 'probe', 1, 'Probe');
    v_steps := v_steps || '{"8_direct_snapshot":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('8_direct_snapshot', case when v_state = '55000' then 'pass' else 'fail:' || v_state end);
  end;

  -- 9. Update and delete are refused, also when they match no row (statement triggers).
  begin
    update public.bank_snapshot_items set position = position where false;
    v_steps := v_steps || '{"9_zero_row_update":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('9_zero_row_update', case when v_state = '55000' then 'pass' else 'fail:' || v_state end);
  end;
  begin
    delete from public.bank_snapshot_items where snapshot_id = v_snapshot;
    v_steps := v_steps || '{"9_delete_items":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('9_delete_items', case when v_state = '55000' then 'pass' else 'fail:' || v_state end);
  end;
  begin
    delete from public.bank_reviews where false;
    v_steps := v_steps || '{"9_zero_row_review_delete":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('9_zero_row_review_delete', case when v_state = '55000' then 'pass' else 'fail:' || v_state end);
  end;

  -- 10. The basis check still refuses a note at any depth, even inside the freeze flag.
  begin
    perform set_config('unica.in_bank_freeze_level', '1', true);
    insert into public.bank_snapshot_items (snapshot_id, kind, key, position, content, hash)
    values (v_snapshot, 'topic', 'basis-probe', 9, '{"id":"basis-probe","rows":[{"basis":{"source":"made-up"}}]}', repeat('0', 64));
    v_steps := v_steps || '{"10_basis_check":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate;
    v_steps := v_steps || jsonb_build_object('10_basis_check', case when v_state = '23514' then 'pass' else 'fail:' || v_state end);
  end;
  perform set_config('unica.in_bank_freeze_level', '', true);

  -- 11. A deleted row that comes back at a reviewed revision is refused.
  delete from public.bank_sheets where sheet_id = v_sheet->>'sheet_id';
  select updated_at::text into v_ver from public.bank_levels where id = v_level;
  begin
    perform public.bank_write_level(jsonb_set(jsonb_set(v_write - 'sheets', '{expected}', to_jsonb(v_ver)), '{sheets}', jsonb_build_array(v_sheet)));
    v_steps := v_steps || '{"11_reinsert_reviewed_revision":"fail:accepted"}';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    v_steps := v_steps || jsonb_build_object('11_reinsert_reviewed_revision', case when v_state = 'PT409' and v_msg like '%comes back%' then 'pass' else 'fail:' || v_state || ' ' || v_msg end);
  end;

  raise exception 'UNI242_PROBE %', jsonb_build_object('steps', v_steps, 'all_pass', not exists (select 1 from jsonb_each_text(v_steps) e where e.value <> 'pass'));
end $probe$;
